    const subtotal=materialUnit+freightBase+freightTax;const calculated=roundUp(subtotal*(1+adjustment),s.roundTo);const manual=l.override!==''&&Number.isFinite(+l.override);const finalUnit=manual?+l.override:calculated;
    const taxInUnit=(materialTaxUnit+freightTax)*(1+adjustment)*(calculated?finalUnit/calculated:1);if(p.taxable==='Confirm')flags.push({text:`CONFIRMAR IMPUESTO · TASA CONFIGURADA ${(s.taxRate*100).toFixed(2)}% · ESTIMADO ${money(taxInUnit*qty)}`,type:'warn'});
    let days=null,trucks=null,dailyLoads=null;
