  function calculateAll(){const calcs=lines.map(l=>calcLine(l,lines));lastCalculations=calcs;calcs.forEach(renderResults);const valid=calcs.filter(x=>!x.empty&&!x.pending);const total=valid.reduce((n,x)=>n+x.extended,0);const taxes=valid.reduce((n,x)=>n+x.taxInUnit*(+x.line.qty),0);const loads=valid.reduce((n,x)=>n+(x.loads||0),0);const trucks=valid.reduce((n,x)=>n+(x.trucks||0),0);const margin=valid.reduce((n,x)=>n+(x.margin||0),0);const marginBase=valid.reduce((n,x)=>n+(x.marginBase||0),0);const marginPct=marginBase?margin/marginBase:null;$('#summary').innerHTML=`<div class="summary-total"><label>Total estimado · impuestos incluidos</label><strong>${money(total)}</strong><small>${money(taxes)} impuesto estimado incluido · tasa configurada ${(config.settings.taxRate*100).toFixed(2)}%</small></div><div class="summary-grid"><div class="summary-stat"><span>Cargas estimadas</span><strong>${loads||'—'}</strong></div><div class="summary-stat"><span>Pico camiones / día</span><strong>${trucks||'—'}</strong></div><div class="summary-stat"><span>Margen estimado</span><strong>${money(margin)}${marginPct===null?'':` · ${(marginPct*100).toFixed(1)}%`}</strong></div><div class="summary-stat"><span>Líneas completas</span><strong>${valid.length} / ${lines.length}</strong></div></div>`;
    const alertEntries=[...calcs.flatMap(c=>c.flags.map(f=>({text:f.text,lineId:c.line?.id,action:f.text.startsWith('60% SOLO CON ENTREGA JCK')?'add-delivery':f.text.startsWith('MARGEN BAJO')?'review-margin':null}))),...(!formData().customer?[{text:"Falta el nombre legal del cliente.",action:'customer'}]:[]),...(!formData().project?[{text:"Falta el nombre del proyecto.",action:'project'}]:[]),...(formData().terms&&formData().terms.includes('Net 3')?[{text:"Net 30 o Net 45 requiere aprobación de crédito previa."}]:[])];const unique=[...new Map(alertEntries.map(a=>[`${a.text}|${a.lineId||''}|${a.action||''}`,a])).values()];$('#alerts').innerHTML=unique.map(a=>{const cls=/PENDIENTE|FALTA|BAJO|INGRESE|SOLO CON/.test(a.text)?'error':'';if(a.action==='add-delivery'||a.action==='review-margin')return `<li class="${cls}"><button type="button" class="alert-jump" data-review-action="${a.action}" data-line-id="${a.lineId||''}"><span>${esc(a.text)}</span><small>${a.action==='add-delivery'?'Ir a añadir entrega':'Revisar precio y costo'} ↗</small></button></li>`;return `<li class="${cls}">${esc(a.text)}</li>`}).join('');}
