  function loadQuote(){try{const q=JSON.parse(localStorage.getItem('jck_quote_draft')||'null');if(!q)return;for(const [k,v] of Object.entries(q.form||{})){const el=$(`[data-field="${k}"]`);if(el)el.value=v}if(q.lines?.length){lines=q.lines.map(x=>({...x,id:++lineSeq}))}}catch{}initTerms();renderLines()}
